<template><GameLayout><div class="section-heading"><p class="kicker">MEMÓRIA DA MESA</p><h2>Histórico</h2><p>Partidas ficam salvas localmente, sem conta e sem internet.</p></div><div v-if="registros.length" class="history-list"><ion-item v-for="registro in registros" :key="registro.id" button :router-link="`/detalhes/${registro.id}`"><ion-label><strong>{{ registro.status === 'finalizada' ? 'Partida concluída' : 'Partida cancelada' }}</strong><p>{{ new Date(registro.inicio).toLocaleDateString('pt-BR') }} · {{ registro.rodadas }} rodadas</p></ion-label><ion-note slot="end">{{ registro.vencedor || 'sem vencedor' }}</ion-note></ion-item></div><div v-else class="empty-state"><strong>Nenhuma partida ainda.</strong><p>Quando uma mesa terminar, ela aparecerá aqui.</p></div></GameLayout></template>
<script setup lang="ts">import { onMounted, ref } from 'vue'; import { IonItem, IonLabel, IonNote } from '@ionic/vue'; import GameLayout from '@/components/GameLayout.vue'; import { historicoService } from '@/services/database/historico'; import type { RegistroHistorico } from '@/types/game'; const registros = ref<RegistroHistorico[]>([]); onMounted(() => { registros.value = historicoService.listar(); });</script>
